'use strict';

// MODULES //

var tape = require( 'tape' );
var hasBigIntSupport = require( '@stdlib/assert/has-bigint-support' );
var BigInt = require( '@stdlib/bigint/ctor' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var isEqual = require( '@stdlib/number/int64/base/assert/is-equal' );
var Int64 = require( '@stdlib/number/int64/ctor' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var mul = require( './../lib' );


// VARIABLES //

var opts = {
	'skip': !hasBigIntSupport()
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof mul, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function multiplies two 64-bit signed integers', function test( t ) {
	var expected;
	var out;
	var a;
	var b;

	// Small value:
	a = new Int64( 5 );
	b = new Int64( 10 );
	out = mul( a, b );
	expected = new Int64( 50 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Negative value:
	a = new Int64( 5 );
	b = new Int64( -10 );
	out = mul( a, b );
	expected = new Int64( -50 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Both negative:
	a = new Int64( -5 );
	b = new Int64( -10 );
	out = mul( a, b );
	expected = new Int64( 50 );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	// Large value:
	a = new Int64( 123456789 );
	b = new Int64( 987654321 );
	out = mul( a, b );
	expected = new Int64( BigInt( '121932631112635269' ) );
	t.ok( isEqual( out, expected ), 'returns expected value' );

	t.end();
});

tape( 'the function multiplies two 64-bit signed integers (random values)', opts, function test( t ) {
	var big64product;
	var expected;
	var values;
	var out;
	var a;
	var b;
	var x;
	var i;

	x = discreteUniform( 100, 0, UINT32_MAX, {
		'dtype': 'uint32'
	});
	values = [];
	for ( i = 0; i < x.length; i++ ) {
		values.push( Int64.of( x[ i ], x[ (i+1)%x.length ] ) );
	}

	for ( i = 0; i < values.length; i++ ) {
		a = values[ i ];
		b = values[ (i+1)%values.length ];
		out = mul( a, b );
		big64product = BigInt.asIntN( 64, a.valueOf() * b.valueOf() );
		expected = new Int64( big64product );
		t.ok( isEqual( out, expected ), 'returns expected value' );
	}

	t.end();
});
